// ── finemap.abf with prior weights ──────────────────────────────────────────

#[test]
fn finemap_abf_with_weights_matches_unweighted() {
    let golden = load_golden();
    let inputs = &golden["inputs"];

    let d = make_dataset_from_inputs(inputs, "DQ");
    let n = d.snp.len();
    let uniform_weights = vec![1.0; n];

    let result_u = finemap_abf(&d, 1e-4, None).unwrap();
    let result_w = finemap_abf(&d, 1e-4, Some(&uniform_weights)).unwrap();

    for i in 0..n {
        assert!(
            (result_u.snps[i].snp_pp - result_w.snps[i].snp_pp).abs() < 1e-14,
            "uniform weights should match no weights at snp {i}"
        );
    }
}
